### Layout

import streamlit as st

st.title("Election Result Poll")

col1, col2 = st.columns(2)

with col1:
    st.header("Election MP")
    st.image("data:image/jpeg;base64,",width=200)
    vote1 = st.button("Vote for MP")

with col2:
    st.header("Election MLA")
    st.image("data:image/jpeg;base64,",width=200)
    vote2 = st.button("Vote for MLA")
    
if vote1:
    st.success(f"Thanks for voting a MP")
elif vote2:
    st.success(f"Thanks for voting a MLA")

name = st.sidebar.text_input("Enter your name")
pol = st.sidebar.selectbox("Choose your politician",["MP","MLA","MLC"])

st.write(f"Welcome {name} and you choose {pol}")

with st.expander("How to be politician"):
    st.write(""" 
    1. To reach everyone.
    2. You should do good work in your constituency.
    3. Always help people.
             
""")
    
st.markdown("# Politics ")
st.markdown(" > Blockquote ")
